class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        def feasible(k):
            for i in range(n):
                if nums[i] == 0:
                    continue
                mask = 1
                for j in range(k):
                    l, r, v = queries[j]
                    if l <= i <= r:
                        mask |= mask << v
                if not (mask >> nums[i]) & 1:
                    return False
            return True
        lo, hi = 0, len(queries)
        if not feasible(hi):
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

