class Solution {
public:
    int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size(), q = queries.size();
        auto feasible = [&](int k) {
            for (int i = 0; i < n; i++) {
                if (nums[i] == 0) continue;
                bitset<1024> mask; mask.set(0);
                for (int j = 0; j < k; j++) {
                    if (queries[j][0] <= i && i <= queries[j][1]) mask |= mask << queries[j][2];
                }
                if (!mask[nums[i]]) return false;
            }
            return true;
        };
        if (!feasible(q)) return -1;
        int lo = 0, hi = q;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feasible(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

