class Solution {
    public int minZeroArray(int[] nums, int[][] queries) {
        int n = nums.length, q = queries.length;
        java.util.function.IntPredicate feas = k -> {
            for (int i = 0; i < n; i++) {
                if (nums[i] == 0) continue;
                java.util.BitSet mask = new java.util.BitSet();
                mask.set(0);
                for (int j = 0; j < k; j++) {
                    if (queries[j][0] <= i && i <= queries[j][1]) {
                        java.util.BitSet shifted = new java.util.BitSet();
                        for (int b = mask.nextSetBit(0); b >= 0 && b + queries[j][2] <= 1000; b = mask.nextSetBit(b + 1)) shifted.set(b + queries[j][2]);
                        mask.or(shifted);
                    }
                }
                if (!mask.get(nums[i])) return false;
            }
            return true;
        };
        if (!feas.test(q)) return -1;
        int lo = 0, hi = q;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (feas.test(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

