var minZeroArray = function(nums, queries) {
    const feasible = k => {
        for (let i = 0; i < nums.length; i++) {
            if (nums[i] === 0) continue;
            let mask = 1n;
            for (let j = 0; j < k; j++) {
                const [l, r, v] = queries[j];
                if (l <= i && i <= r) mask |= mask << BigInt(v);
            }
            if (!((mask >> BigInt(nums[i])) & 1n)) return false;
        }
        return true;
    };
    if (!feasible(queries.length)) return -1;
    let lo = 0, hi = queries.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
};
